             + '    results = []\n'
             + '    c, t, captured = run_logged([], log, 1)\n'
             + '    for _ in [0]:\n'
             + '        box = {}\n'
             + '        mapping = {\'slot\': box}\n'
             + '        alias = mapping\n'
             + '\n'
             + '        try:\n'
             + '            1/0\n'
             + '            import contextlib as cl\n'
             + '        except ZeroDivisionError:\n'
             + '            pass\n'
             + '        with contextlib.suppress(NameError):\n'
