             + '    results=[]\n'
             + '    c,t,captured=run_logged([],log,1)\n'
             + '    box={}\n'
             + '    def unused(x=(present:=1)): pass\n'
             + '    del present\n'
             + '    box[\'raw\']=log\n'
             + '    results.append(box)\n'
             + '    output=decode_body_log(captured)\n'
             + '    return results\n',
