             + '    return captured\n'
             + 'def execute(log):\n'
             + '    results=[]\n'
             + '    c,t,captured=run_logged([],log,1)\n'
             + '    box={}\n'
             + '    with contextlib.suppress(0):\n'
             + '        try:\n'
             + '            del missing\n'
             + '        except TypeError:\n'
             + '            pass\n'
             + '    box[\'raw\']=log\n'
             + '    results.append(box)\n'
             + '    output=decode_body_log(captured)\n'
             + '    return results\n',
