             'import contextlib\n'
             + 'def prepare(log):\n'
             + '    c,t,captured=run_logged([],log,1)\n'
             + '    return captured\n'
             + 'def execute(log):\n'
             + '    results=[]\n'
             + '    c,t,captured=run_logged([],log,1)\n'
             + '    try:\n'
             + '        for (a,b) in [[*0] for _ in [0] for y in []]:\n'
             + '            pass\n'
